import http from 'node:http';
import { readFile, writeFile, mkdir, rename, unlink } from 'node:fs/promises';
import { randomUUID } from 'node:crypto';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = dirname(fileURLToPath(import.meta.url));
const defaultFile = join(root, 'data', 'books.json');
const assets = new Map([
  ['/styles.css', ['text/css; charset=utf-8', join(root, 'public', 'styles.css')]],
  ['/app.js', ['text/javascript; charset=utf-8', join(root, 'public', 'app.js')]],
]);

function reply(res, status, value) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' });
  res.end(JSON.stringify(value));
}

async function readBooks(file) {
  try {
    const books = JSON.parse(await readFile(file, 'utf8'));
    if (!Array.isArray(books)) throw new Error('Book file must contain an array');
    return books;
  } catch (error) {
    if (error.code === 'ENOENT') return [];
    throw error;
  }
}

async function saveBooks(file, books) {
  await mkdir(dirname(file), { recursive: true });
  const temporary = `${file}.${randomUUID()}.tmp`;
  try {
    await writeFile(temporary, `${JSON.stringify(books, null, 2)}\n`, 'utf8');
    await rename(temporary, file);
  } catch (error) {
    await unlink(temporary).catch(() => {});
    throw error;
  }
}

async function readBody(req) {
  let body = '';
  for await (const chunk of req) {
    body += chunk;
    if (body.length > 12000) {
      const error = new Error('Request is too large');
      error.status = 413;
      throw error;
    }
  }
  try {
    return JSON.parse(body);
  } catch {
    const error = new Error('Invalid JSON');
    error.status = 400;
    throw error;
  }
}

function validateBook(input) {
  if (!input || typeof input !== 'object' || Array.isArray(input)) return 'Enter a title and author.';
  if (typeof input.title !== 'string' || !input.title.trim() || input.title.trim().length > 160) return 'Title must be 1–160 characters.';
  if (typeof input.author !== 'string' || !input.author.trim() || input.author.trim().length > 120) return 'Author must be 1–120 characters.';
  if (input.notes !== undefined && (typeof input.notes !== 'string' || input.notes.trim().length > 5000)) return 'Notes must be 5,000 characters or fewer.';
  return null;
}

export function createServer({ file = process.env.BOOKS_FILE || defaultFile } = {}) {
  // Serialize writes so two quick requests cannot overwrite one another's changes.
  let pending = Promise.resolve();
  function mutate(fn) {
    const next = pending.then(async () => {
      const books = await readBooks(file);
      const result = await fn(books);
      if (result.save) await saveBooks(file, books);
      return result;
    });
    pending = next.catch(() => {});
    return next;
  }

  return http.createServer(async (req, res) => {
    try {
      const path = new URL(req.url, 'http://localhost').pathname;
      if (path === '/api/books' && req.method === 'GET') {
        await pending;
        return reply(res, 200, await readBooks(file));
      }
      if (path === '/api/books' && req.method === 'POST') {
        const input = await readBody(req);
        const problem = validateBook(input);
        if (problem) return reply(res, 400, { error: problem });
        const result = await mutate(books => {
          const book = {
            id: randomUUID(),
            title: input.title.trim(),
            author: input.author.trim(),
            notes: (input.notes || '').trim(),
            status: 'reading',
            createdAt: new Date().toISOString(),
            finishedAt: null,
          };
          books.unshift(book);
          return { status: 201, book, save: true };
        });
        return reply(res, result.status, result.book);
      }
      const bookRoute = path.match(/^\/api\/books\/([0-9a-f-]{36})$/i);
      if (bookRoute) {
        const id = bookRoute[1];
        if (req.method === 'GET') {
          await pending;
          const book = (await readBooks(file)).find(item => item.id === id);
          return reply(res, book ? 200 : 404, book || { error: 'Book not found.' });
        }
        if (req.method === 'PATCH') {
          const input = await readBody(req);
          if (!input || input.status !== 'finished') return reply(res, 400, { error: 'Only marking a book as finished is supported.' });
          const result = await mutate(books => {
            const book = books.find(item => item.id === id);
            if (!book) return { status: 404, book: { error: 'Book not found.' }, save: false };
            if (book.status === 'finished') return { status: 200, book, save: false };
            book.status = 'finished';
            book.finishedAt = new Date().toISOString();
            return { status: 200, book, save: true };
          });
          return reply(res, result.status, result.book);
        }
        if (req.method === 'DELETE') {
          const result = await mutate(books => {
            const index = books.findIndex(item => item.id === id);
            if (index === -1) return { status: 404, save: false };
            books.splice(index, 1);
            return { status: 204, save: true };
          });
          if (result.status === 204) { res.writeHead(204); return res.end(); }
          return reply(res, 404, { error: 'Book not found.' });
        }
      }
      if (req.method === 'GET') {
        const asset = assets.get(path);
        if (asset) {
          res.writeHead(200, { 'Content-Type': asset[0] });
          return res.end(await readFile(asset[1]));
        }
        if (path === '/' || /^\/books\/[0-9a-f-]{36}\/?$/i.test(path)) {
          res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' });
          return res.end(await readFile(join(root, 'public', 'index.html')));
        }
      }
      return reply(res, 404, { error: 'Not found.' });
    } catch (error) {
      if (error.status) return reply(res, error.status, { error: error.message });
      console.error(error);
      return reply(res, 500, { error: 'Could not access the book collection.' });
    }
  });
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const port = Number(process.env.PORT) || 3000;
  createServer().listen(port, () => console.log(`Folio is ready at http://localhost:${port}`));
}

