{"path":"public/app.js","content":"const app = document.querySelector('#app');
const dialog = document.querySelector('#add-dialog');
const form = document.querySelector('#add-form');
const toast = document.querySelector('#toast');
let books = [];
let toastTimer;

const icons = {
  plus: '<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M12 5v14M5 12h14" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>',
  arrow: '<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>',
  check: '<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="m5 12 4.5 4.5L19 7" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>',
  link: '<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M10 13a5 5 0 0 0 7.5.5l2-2a5 5 0 0 0-7.1-7.1l-1.1 1.1M14 11a5 5 0 0 0-7.5-.5l-2 2a5 5 0 0 0 7.1 7.1l1.1-1.1" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/></svg>',
};

function escapeHTML(value) {
  return String(value ?? '').replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);
}

function colorFor(book) {
  let hash = 0;
  for (const char of book.id) hash = (hash * 31 + char.charCodeAt(0)) | 0;
  return Math.abs(hash) % 6;
}

function cover(book, size = '') {
  return `<div class="book-cover cover-${colorFor(book)} ${size}" aria-hidden="true"><div class="cover-top">FOLIO <span>✳</span></div><div class="cover-center"><span class="cover-ornament">✦</span><span class="cover-title">${escapeHTML(book.title)}</span><span class="cover-author">${escapeHTML(book.author)}</span></div><div class="cover-bottom">✳ &nbsp; ✳ &nbsp; ✳</div></div>`;
}

function showToast(message) {
  toast.textContent = message;
  toast.classList.add('visible');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toast.classList.remove('visible'), 3500);
}

async function request(path, options) {
  const response = await fetch(path, {
    ...options,
    headers: { 'Content-Type': 'application/json', ...options?.headers },
  });
  if (response.status === 204) return null;
  const result = await response.json();
  if (!response.ok) throw new Error(result.error || 'Something went wrong. Please try again.');
  return result;
}

function updateChrome() {
  document.querySelector('#nav-count').textContent = books.length;
  const isDetail = location.pathname.startsWith('/books/');
  document.querySelector('#topbar-current').textContent = isDetail ? 'BOOK DETAILS' : 'OVERVIEW';
  document.querySelector('#nav-library').classList.toggle('active', !isDetail);
}

function readingCard(book, index) {
  return `<article class="book-card" style="--card-index:${index}">
    <a href="/books/${book.id}" data-link class="card-cover-link" aria-label="View ${escapeHTML(book.title)}">${cover(book)}</a>
    <div class="card-content">
      <div class="card-kicker"><span class="status-dot"></span> CURRENTLY READING <span class="card-number">${String(index + 1).padStart(2, '0')}</span></div>
      <a href="/books/${book.id}" data-link class="card-title">${escapeHTML(book.title)}</a>
      <p class="card-author">by ${escapeHTML(book.author)}</p>
      ${book.notes ? `<p class="card-excerpt">${escapeHTML(book.notes)}</p>` : '<p class="card-excerpt card-excerpt-empty">Your next favorite story is unfolding.</p>'}
      <button type="button" class="text-action" data-finish="${book.id}">Mark as finished ${icons.arrow}</button>
    </div>
  </article>`;
}

function finishedCard(book) {
  return `<article class="finished-card">
    <a href="/books/${book.id}" data-link class="finished-cover-link" aria-label="View ${escapeHTML(book.title)}">${cover(book, 'cover-small')}</a>
    <div class="finished-content"><div class="finished-kicker">${icons.check} FINISHED ${book.finishedAt ? `· ${new Date(book.finishedAt).toLocaleDateString(undefined, { month: 'short', year: 'numeric' }).toUpperCase()}` : ''}</div>
      <a href="/books/${book.id}" data-link class="finished-title">${escapeHTML(book.title)}</a><p class="finished-author">${escapeHTML(book.author)}</p>
      <a href="/books/${book.id}" data-link class="finished-view">View book ${icons.arrow}</a></div>
  </article>`;
}

function renderHome() {
  document.title = 'Folio — Your reading space';
  const reading = books.filter(book => book.status !== 'finished');
  const finished = books.filter(book => book.status === 'finished').sort((a, b) => (b.finishedAt || '').localeCompare(a.finishedAt || ''));
  app.innerHTML = `<div class="home-page">
    <section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="eyebrow-line"></span> A READING JOURNAL, JUST FOR YOU</div><h1>Between the <em>pages.</em></h1><p>A little corner for the books you're in the middle of, and the ones you'll carry with you.</p><button type="button" class="button button-primary hero-button" data-add>${icons.plus} Add a book</button></div><div class="hero-art" aria-hidden="true"><div class="art-orbit orbit-one"></div><div class="art-orbit orbit-two"></div><div class="art-star star-one">✳</div><div class="art-star star-two">✦</div><div class="art-book art-book-back"></div><div class="art-book art-book-middle"></div><div class="art-book art-book-front"><span>stories<br/>worth<br/><i>keeping.</i></span><small>✦ &nbsp; ✦ &nbsp; ✦</small></div><div class="art-caption">YOUR STORY IS STILL UNFOLDING ↗</div></div></section>
    <div class="overview-bar"><div><span class="overview-label">ON YOUR SHELF</span><strong>${books.length}</strong><span>${books.length === 1 ? 'book' : 'books'} in your collection</span></div><div class="overview-separator"></div><div><span class="overview-label">IN THE MIDDLE OF</span><strong>${reading.length}</strong><span>still turning pages</span></div><div class="overview-separator"></div><div><span class="overview-label">THE LAST PAGE</span><strong>${finished.length}</strong><span>stories finished</span></div></div>
    <section class="shelf-section reading-section" id="reading"><div class="section-heading"><div><div class="eyebrow section-eyebrow">01 / THE NOW</div><h2>Currently reading <span class="section-count">${String(reading.length).padStart(2, '0')}</span></h2><p>Good things take time. Here's what's on your nightstand.</p></div><button type="button" class="button button-outline section-button" data-add>${icons.plus} Add a book</button></div>
    ${reading.length ? `<div class="reading-grid">${reading.map(readingCard).join('')}</div>` : `<div class="empty-state"><span class="empty-symbol">✳</span><h3>A fresh page awaits.</h3><p>Your reading shelf is empty for now. Add a book to start your next chapter.</p><button type="button" class="button button-primary" data-add>${icons.plus} Add your first book</button></div>`}</section>
    <section class="shelf-section finished-section" id="finished"><div class="section-heading"><div><div class="eyebrow section-eyebrow">02 / THE MEMORIES</div><h2>Finished books <span class="section-count">${String(finished.length).padStart(2, '0')}</span></h2><p>The ones you closed, but never quite left behind.</p></div></div>
    ${finished.length ? `<div class="finished-grid">${finished.map(finishedCard).join('')}</div>` : `<div class="finished-empty"><span>✦</span> Every ending starts with a first page. Finished books will live here.</div>`}</section>
    <div class="end-note">Here's to the stories still to come <span>✳</span></div>
  </div>`;
  if (location.hash) requestAnimationFrame(() => document.querySelector(location.hash)?.scrollIntoView());
}

function renderDetail(book) {
  document.title = `${book.title} — Folio`;
  const finished = book.status === 'finished';
  app.innerHTML = `<div class="detail-page"><a href="/" data-link class="back-link"><span aria-hidden="true">←</span> Back to my library</a>
    <div class="detail-layout"><div class="detail-cover-wrap">${cover(book, 'cover-large')}<div class="cover-footnote">A STORY ON YOUR SHELF <span>✳</span></div></div>
    <div class="detail-content"><div class="eyebrow detail-eyebrow"><span class="eyebrow-line"></span> ${finished ? 'A STORY FINISHED' : 'ON YOUR NIGHTSTAND'}</div><h1>${escapeHTML(book.title)}<span class="accent-dot">.</span></h1><p class="detail-author">by <strong>${escapeHTML(book.author)}</strong></p>
    <div class="detail-divider"></div><div class="detail-meta"><div><span>STATUS</span><strong class="detail-status ${finished ? 'is-finished' : ''}"><span class="status-dot"></span>${finished ? 'Finished' : 'Currently reading'}</strong></div><div><span>ADDED TO SHELF</span><strong>${new Date(book.createdAt).toLocaleDateString(undefined, { month: 'long', day: 'numeric', year: 'numeric' })}</strong></div>${finished && book.finishedAt ? `<div><span>FINISHED</span><strong>${new Date(book.finishedAt).toLocaleDateString(undefined, { month: 'long', day: 'numeric', year: 'numeric' })}</strong></div>` : ''}</div>
    <div class="detail-notes"><div class="notes-heading"><span class="eyebrow">MARGINALIA</span><span class="notes-star" aria-hidden="true">✳</span></div><h2>My notes</h2>${book.notes ? `<p class="note-text">${escapeHTML(book.notes).replace(/\n/g, '<br>')}</p>` : '<p class="note-placeholder">No notes yet. Some stories leave their mark without words.</p>'}</div>
    <div class="detail-actions">${finished ? '' : `<button type="button" class="button button-primary" data-finish="${book.id}">${icons.check} Mark as finished</button>`}<button type="button" class="button button-outline" data-copy> ${icons.link} Copy book link</button></div>
    <button type="button" class="delete-button" data-delete="${book.id}">Remove from my library</button></div></div>
    <div class="detail-end">A little space for the stories that stay with us. <span>✦</span></div>
  </div>`;
}

async function render() {
  updateChrome();
  const match = location.pathname.match(/^\/books\/([0-9a-f-]{36})\/?$/i);
  if (match) {
    try {
      const book = await request(`/api/books/${match[1]}`);
      renderDetail(book);
    } catch (error) {
      app.innerHTML = `<div class="not-found"><div class="eyebrow">A MISSING CHAPTER</div><h1>Book not found<span class="accent-dot">.</span></h1><p>This book might have been removed, or the link may be wrong.</p><a href="/" data-link class="button button-primary">Back to my library ${icons.arrow}</a></div>`;
      document.title = 'Book not found — Folio';
