import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { mkdtemp, readFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { createServer } from '../server.js';

let directory;
let file;
let server;
let base;

async function start() {
  server = createServer({ file });
  await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
  base = `http://127.0.0.1:${server.address().port}`;
}
async function stop() {
  await new Promise((resolve, reject) => server.close(error => error ? reject(error) : resolve()));
}
async function json(path, options) {
  const response = await fetch(`${base}${path}`, { ...options, headers: { 'Content-Type': 'application/json' } });
  return { status: response.status, body: response.status === 204 ? null : await response.json() };
}

beforeEach(async () => {
  directory = await mkdtemp(join(tmpdir(), 'folio-test-'));
  file = join(directory, 'nested', 'books.json');
  await start();
});
afterEach(async () => {
  await stop();
  await rm(directory, { recursive: true, force: true });
});

describe('book collection', () => {
  it('adds, lists, retrieves, finishes, and preserves a book across server restarts', async () => {
    expect((await json('/api/books')).body).toEqual([]);
    const created = await json('/api/books', { method: 'POST', body: JSON.stringify({ title: '  The Left Hand of Darkness  ', author: ' Ursula K. Le Guin ', notes: ' A favorite. ' }) });
    expect(created.status).toBe(201);
    expect(created.body).toMatchObject({ title: 'The Left Hand of Darkness', author: 'Ursula K. Le Guin', notes: 'A favorite.', status: 'reading', finishedAt: null });
    const id = created.body.id;
    expect((await json('/api/books')).body).toHaveLength(1);
    expect((await json(`/api/books/${id}`)).body.id).toBe(id);
    expect((await fetch(`${base}/books/${id}`)).status).toBe(200);
    const finished = await json(`/api/books/${id}`, { method: 'PATCH', body: JSON.stringify({ status: 'finished' }) });
    expect(finished.body.status).toBe('finished');
    expect(finished.body.finishedAt).toBeTruthy();
    expect((await json(`/api/books/${id}`, { method: 'PATCH', body: JSON.stringify({ status: 'finished' }) })).body.finishedAt).toBe(finished.body.finishedAt);
    await stop();
    await start();
    expect((await json(`/api/books/${id}`)).body).toEqual(finished.body);
    expect(JSON.parse(await readFile(file, 'utf8'))).toEqual([finished.body]);
  });

  it('keeps concurrent additions and allows removing a book', async () => {
    const results = await Promise.all(Array.from({ length: 8 }, (_, index) => json('/api/books', { method: 'POST', body: JSON.stringify({ title: `Book ${index}`, author: 'Someone' }) })));
    expect(results.every(result => result.status === 201)).toBe(true);
    expect((await json('/api/books')).body).toHaveLength(8);
    const id = results[0].body.id;
    expect((await json(`/api/books/${id}`, { method: 'DELETE' })).status).toBe(204);
    expect((await json(`/api/books/${id}`)).status).toBe(404);
    expect((await json('/api/books')).body).toHaveLength(7);
  });

  it('rejects invalid input and unknown routes', async () => {
    expect((await json('/api/books', { method: 'POST', body: JSON.stringify({ title: '', author: 'Someone' }) })).status).toBe(400);
    expect((await json('/api/books', { method: 'POST', body: '{oops' })).status).toBe(400);
    expect((await json('/api/books/not-a-book')).status).toBe(404);
    expect((await fetch(`${base}/books/not-a-book`)).status).toBe(404);
    expect((await json('/api/books')).body).toEqual([]);
  });
});

